import functools

def tag(label):
    def deco(fn):
        @functools.wraps(fn)
        def wrapper(*args):
            return f"<{label}>" + fn(*args)
        return wrapper
    return deco

@tag("a")
@tag("b")
def name(x):
    return x.upper()

print(name("sku"))
